(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.3) * 18 + Math.cos(y * 0.013 - t * 0.2) * 12;
  const w1y = Math.cos(y * 0.016 - t * 0.25) * 18 + Math.sin(x * 0.015 + t * 0.35) * 12;
  const w2x = Math.sin((x + w1x) * 0.025 - t * 0.4) * 8;
  const w2y = Math.cos((y + w1y) * 0.022 + t * 0.45) * 8;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.14, 1.3, 0.7],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*40, 0.11, 2.1, 1.05]
  ];
  let aS = 0, iS = 0, wS = 0, tw = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * wt;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * wt;
    wS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.0) * wt;
    tw += wt;
  }
  const act = aS/tw, inh = iS/tw, wave = wS/tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35+Math.sin(dist*0.07+ang*2-t*0.8)*0.2+Math.sin(dist*0.03-t*2)*0.15;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((act*0.8 - inh + wave*0.4 + bg*0.2)*1.8);
  const rdMix = rd1*0.6 + rd2*0.4;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.1;
  const blend = rdMix*0.6+cell*0.2+micro*0.1+spiral*0.1;
  const v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.15)*0.08;
  const pv = ((v+hueShift)%1+1)%1;
  const pal = [[5,10,45],[12,35,85],[18,70,120],[20,120,130],[25,160,140],[140,190,100],[220,195,60],[230,150,55],[210,100,60],[160,50,55],[90,25,60],[40,15,55],[10,10,45],[5,10,45]];
  const idx = pv*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const gf = f*f*(3-2*f);
  const lum = 0.75+Math.sin(rdMix*Math.PI)*0.25;
  const edge = Math.abs(rdMix)>0.85?1.3:Math.abs(rdMix)>0.65?1.15:1.0;
